import csv, statistics
from collections import defaultdict

def parse_int(x):
    try: return int(float(x))
    except: return None

rows=[]
with open('benchmark/data.csv', newline='', encoding='utf-8') as f:
    r=csv.DictReader(f)
    for row in r:
        rows.append((parse_int(row['turns']), row['victory_status']))

by=defaultdict(list)
for t,vs in rows:
    if t is not None:
        by[vs].append(t)

for vs in ['mate','resign','outoftime','draw']:
    arr=by[vs]
    print(vs,'n',len(arr),'avg',sum(arr)/len(arr),'median',statistics.median(arr))
PY

